'use strict';
const assert=require('node:assert/strict'),Campaign=require('../src/prototype/engine.js'),D=Campaign.data,Visuals=require('../src/prototype/visuals.js');
let passed=0;function test(name,fn){try{fn();passed++;console.log('PASS '+name);}catch(e){process.exitCode=1;console.error('FAIL '+name+'\n'+e.stack);}}
const fresh=(r=.9,options={})=>new Campaign('normal','paladin',()=>r,options);
function slay(c,e,hero=true){Object.assign(c.hero,c.safe(e.x,e.y));e.heroParticipated=hero;e.hp=0;c.kill(e);}
function boss(c,id,form='normal'){const b=c.boss(id);c.enter(b.kind==='dungeon'?id:b.region);let e=c.zone().enemies.find(e=>e.family===id&&e.form===form&&e.hp>0);if(!e){e=c.bossEnemy(b,form,{x:c.hero.x+100,y:c.hero.y});c.zone().enemies.push(e);}return e;}
function settle(c,n=40){for(let i=0;i<n;i++)c.tick(.1);}
test('All three classes start with one skill and valid save round trips',()=>{for(const id of Object.keys(Campaign.classes)){const c=new Campaign('normal',id);assert.deepEqual(c.hero.skills,[1,0,0,0,0,0,0,0]);assert.deepEqual(Campaign.restore(c.snapshot()).snapshot(),c.snapshot());}});
test('New campaigns grant ten seconds of mercy against proximity aggro from hero or companions',()=>{const c=fresh(),e=c.zone().enemies.find(x=>x.type==='mob'&&x.hp>0&&!x.neutral);assert.equal(c.s.mercyTime,10);const h=c.safe(520,350),p=c.safe(h.x+90,h.y);assert(Math.hypot(h.x-300,h.y-350)>170&&Math.hypot(h.x-300,h.y-350)<Campaign.mercyStartRadius,'test point is outside refuge safety but inside mercy leash');Object.assign(c.hero,h);Object.assign(e,p,{home:{...p},aggro:false});const ally=c.s.party[0];Object.assign(ally,{x:e.x+35,y:e.y});for(let n=0;n<50;n++)c.tick(.1);assert(c.s.mercyTime>4.9&&c.s.mercyTime<5.1);assert.equal(e.aggro,false,'nearby hero and companion cannot trigger aggro during mercy outside refuge safety');});
test('Attacking first waives mercy only for the attacked enemy and suppresses pack cascade',()=>{const c=fresh(),mobs=c.zone().enemies.filter(e=>e.type==='mob'&&!e.neutral&&e.hp>0).slice(0,2),[a,b]=mobs;assert(a&&b);const p=c.safe(c.hero.x+75,c.hero.y);Object.assign(a,p,{home:{...p},pack:'mercy-pack',aggro:false});Object.assign(b,c.safe(p.x+45,p.y),{home:c.safe(p.x+45,p.y),pack:'mercy-pack',aggro:false});const before=a.hp;assert(c.damage(a,5,'hero'));assert(a.hp<before&&a.aggro,'attacked enemy fights back immediately');assert.equal(b.aggro,false,'unattacked pack mate remains under mercy');assert(a.mercyProvoked);});
test('Mercy expires after ten seconds of active simulation and normal proximity aggro resumes',()=>{const c=fresh(),e=c.zone().enemies.find(x=>x.type==='mob'&&x.hp>0&&!x.neutral),h=c.safe(520,350),p=c.safe(h.x+90,h.y);Object.assign(c.hero,h);Object.assign(e,p,{home:{...p},aggro:false});for(let n=0;n<99;n++)c.tick(.1);assert(c.s.mercyTime>0,'mercy remains before ten seconds');assert.equal(e.aggro,false);c.tick(.1);assert.equal(c.s.mercyTime,0);assert(e.aggro,'normal proximity aggro resumes on the first hostile-ground AI update at ten seconds');});
test('Mercy remaining survives save reload, while old saves and legacy migrations never receive a fresh grace window',()=>{const c=fresh();for(let n=0;n<37;n++)c.tick(.1);const remaining=c.s.mercyTime,r=Campaign.restore(c.snapshot());assert(Math.abs(r.s.mercyTime-remaining)<1e-9,'reload preserves remaining mercy');const old=c.snapshot();delete old.mercyTime;const oldRestored=Campaign.restore(old);assert.equal(oldRestored.s.mercyTime,0,'pre-mercy save does not get a new window');});
test('Mercy counts down inside the start refuge and cancels early when the hero leaves the start-area leash',()=>{const c=fresh();assert.equal(Campaign.mercyStartRadius,300);for(let n=0;n<30;n++)c.tick(.1);assert(c.s.mercyTime>6.9&&c.s.mercyTime<7.1,'time spent safely in Millhaven still consumes mercy');const inside=c.safe(300+Campaign.mercyStartRadius-20,350);Object.assign(c.hero,inside);c.tick(.1);assert(c.s.mercyTime>0,'small excursion outside the refuge but inside the mercy leash is tolerated');const outside=c.safe(300+Campaign.mercyStartRadius+35,350);Object.assign(c.hero,outside);c.tick(.1);assert.equal(c.s.mercyTime,0,'leaving the introductory area cancels mercy immediately');});
test('Changing zones during the opening window cancels mercy instead of carrying it elsewhere',()=>{const c=fresh();assert(c.s.mercyTime>0);c.enter('march');c.tick(.1);assert.equal(c.s.mercyTime,0);});


test('Every town, cage, transport, dungeon and boss is reachable on the terrain graph',()=>{const c=fresh();for(const r of D.regions){c.enter(r.id);for(const n of c.zone().npcs){assert(!c.blocked(n.x,n.y),r.id+' blocked '+n.id);assert(c.route(c.hero,n).length,r.id+' unreachable '+n.id);}const e=c.zone().enemies.find(e=>e.type==='boss');assert(c.route(c.hero,e.home).length,r.id+' boss');}for(const id of Campaign.dungeonIds){c.enter(id);for(const n of c.zone().npcs)assert(c.route(c.hero,n).length,id+' '+n.id);assert(c.route(c.hero,c.zone().enemies.find(e=>e.type==='boss').home).length,id);}});
test('Authored larger populations retain lower rewards and finite resources',()=>{const c=fresh();let mobs=0,guards=0;for(const r of D.regions){c.enter(r.id);mobs+=c.zone().enemies.filter(e=>e.type==='mob'&&!e.captain&&!e.roomCaptain).length;assert.equal(c.zone().nodes[0].amount,r.resource);}for(const id of Campaign.dungeonIds){c.enter(id);guards+=c.zone().enemies.filter(e=>e.guard).length;}assert.equal(mobs,240);assert.equal(guards,90);assert.deepEqual(c.reward(40,100,1),{gold:40,xp:100});c.hero.level=7;assert.deepEqual(c.reward(40,100,1),{gold:0,xp:0});});
test('Ranged combat uses readable projectile identities instead of generic orbs',()=>{for(const [heroClass,style]of [['ranger','arrow'],['mage','magic']]){const c=new Campaign('normal',heroClass,()=>.9),e=c.zone().enemies.find(e=>e.type==='mob'&&e.hp>0);Object.assign(c.hero,c.safe(e.x+80,e.y));c.hero.cd[0]=0;c.s.projectiles=[];assert(c.cast(1,e.id));assert.equal(c.s.projectiles.at(-1).style,style,heroClass+' basic projectile style');}const c=fresh();const e=c.zone().enemies.find(e=>e.type==='mob'&&e.hp>0);Object.assign(c.hero,c.safe(e.x+120,e.y+30));const archer=c.unit('archer',e.x+220,e.y);c.s.party=[archer];c.s.recallActive=false;c.engage(e);e.heroParticipated=true;for(let i=0;i<50&&!c.s.projectiles.some(p=>p.source===archer.id&&p.style==='arrow');i++)c.updateParty(.1);assert(c.s.projectiles.some(p=>p.source===archer.id&&p.style==='arrow'),'companion archer fires arrows');c.enter('frontier');assert(c.zone().enemies.some(e=>e.species==='orc'&&e.projectileStyle==='axe'),'orc axe throwers use axe projectiles');c.enter('march');const w=c.makeEnemy({species:'wraith',name:'Wraith',level:6,hp:100,damage:10,gold:0,xp:0},{x:500,y:500});c.configureEnemy(w,0);assert.equal(w.projectileStyle,'spectral');});
test('Learning and rank advancement require rescue and funds but never hero level',()=>{const c=fresh();assert.equal(c.hero.level,1);assert(!c.learn(2,'thorn'));slay(c,boss(c,'thorn'));assert(c.rescue('thorn'));c.hero.gold=100;assert(c.learn(2,'thorn'));assert.equal(c.hero.gold,60);assert(!c.learn(2,'thorn'));assert(c.upgrade(2,'thorn'));assert.equal(c.hero.skills[1],2);assert(!c.upgrade(2,'thorn'));});
test('Supplies, smith tiers and tonics spend gold and cannot duplicate purchases',()=>{const c=fresh();c.hero.gold=1000;assert(c.buyPotion('health'));assert.equal(c.hero.gold,980);assert(!c.buyPotion('tonic'));c.s.rescued.archive=true;const hp=c.hero.maxHp;assert(c.buyPotion('tonic'));assert.equal(c.hero.maxHp,hp+Math.ceil(hp*.1));assert(!c.buyPotion('tonic'));c.rest();assert.equal(c.hero.maxHp,hp);c.s.rescued.crypt=true;assert(c.gear('crypt','weapon'));assert(!c.gear('crypt','weapon'));assert(c.gear('crypt','weapon',true));assert(!c.gear('crypt','weapon',true));});
test('Better acquired weapons auto-equip while stronger owned weapons remain equipped',()=>{const c=fresh();c.hero.gold=5000;c.s.rescued.crypt=true;c.s.legacyInventory=['Arma de la Frontera'];c.autoEquipBestWeapon();assert(c.hero.legacyEquipped);assert.equal(c.hero.legacyWeaponPower,40);assert(c.gear('crypt','weapon'));assert(c.hero.legacyEquipped);c.s.rescued.abyss=true;assert(c.gear('abyss','weapon'));assert(!c.hero.legacyEquipped);assert.equal(c.hero.weapon,3);assert.equal(c.weaponTierBonus(),55);});
test('Higher armor tiers immediately become the active armor',()=>{const c=fresh();c.hero.gold=5000;c.s.rescued.crypt=true;c.s.rescued.mine=true;assert(c.gear('crypt','armor'));assert.equal(c.hero.armorTier,1);assert(c.gear('mine','armor'));assert.equal(c.hero.armorTier,2);assert.equal(c.armor(),c.hero.armor+12);});
test('Two hero participating kills trigger two leaders at the 50% branch',()=>{const c=fresh(.2),e=c.zone().enemies.find(e=>e.type==='mob');c.streak(e);assert.equal(c.s.streak.count,1);c.streak(e);assert.equal(c.s.pending[e.species].count,2);c.updateElites(3);assert.equal(c.zone().enemies.filter(x=>x.form==='ringleader').length,2);});
test('Companion-only kills neither advance nor reset streak; hero participation qualifies last hits',()=>{const c=fresh();const a=c.zone().enemies.find(e=>e.species==='goblin'),b=c.zone().enemies.find(e=>e.species==='skeleton');slay(c,a);assert.equal(c.s.streak.count,1);slay(c,b,false);assert.equal(c.s.streak.count,1);const a2=c.zone().enemies.find(e=>e.species==='goblin'&&e.hp>0);slay(c,a2);assert.equal(c.s.pending.goblin.count,1);});
test('Mixed species resets; summons are killable and grant no streak, gold or XP',()=>{const c=fresh();c.streak(c.zone().enemies.find(e=>e.species==='goblin'));c.streak(c.zone().enemies.find(e=>e.species==='skeleton'));assert.equal(c.s.streak.key,'skeleton');assert.equal(c.s.streak.count,1);const e=c.makeEnemy({species:'summon',name:'summon',level:1,hp:1,damage:1,gold:0,xp:0},{x:c.hero.x+30,y:c.hero.y});e.summon=true;c.zone().enemies.push(e);const xp=c.hero.xp,loot=c.s.loot.length;assert(c.cast(1,e.id));assert.equal(e.hp,0);assert.equal(c.hero.xp,xp);assert.equal(c.s.loot.length,loot);assert.equal(c.s.streak.count,1);});
test('Supply-room captains are larger boss-disciple minibosses with original translated movesets',()=>{const expected={vale:['supply-vale','thorn','goblin'],march:['supply-march','mire','mireling'],highlands:['supply-highlands','ridge','wolf'],crown:['supply-crown','darklord','ashbeast']};for(const [region,[roomId,mentor,species]]of Object.entries(expected)){const c=fresh(.41);c.enter(roomId);const z=c.zone(),captains=z.enemies.filter(e=>e.roomCaptain&&e.hp>0);assert.equal(captains.length,1,roomId+' one captain');const e=captains[0],profile=Campaign.rules.roomCaptains[roomId],regular=z.enemies.find(x=>x.roomGuard&&!x.roomCaptain);assert(profile,roomId+' profile');assert.equal(e.species,species,roomId+' keeps regional creature identity');assert.equal(e.captainMentor,mentor,roomId+' mentor');assert.equal(e.name,profile.name);assert(e.visualScale>1&&e.visualScale<=1.25,'moderately larger');assert(Visuals.height({...regular,renderKind:'enemy'})<Visuals.height({...e,renderKind:'enemy'}),'captain visual height');const ri=c.regionIndex(),guardian=Campaign.rules.guardianScaling[ri];assert.equal(e.baseHp,Math.round((65+ri*105)*2*guardian.hp),roomId+' captain HP');assert.equal(e.baseDamage,Math.round((7+ri*8)*1.25*guardian.damage),roomId+' captain damage');assert.equal(profile.attacks.length,3,roomId+' moveset');const bossKinds=new Set(Campaign.rules.attacks[mentor].map(a=>a.kind)),captainKinds=new Set(profile.attacks.map(a=>a.kind));assert([...captainKinds].filter(k=>bossKinds.has(k)).length>=2,roomId+' translates mentor combat language');const bossNames=new Set(c.boss(mentor).attacks.map(x=>x.split(':')[0].trim()));assert(profile.attacks.every(a=>!bossNames.has(a.name)),roomId+' does not copy boss move names');c.s.party=[];Object.assign(c.hero,c.safe(e.x+180,e.y));assert(c.startCaptainAttack(e,c.hero));assert(e.telegraph?.captainSkill&&profile.attacks.some(a=>a.name===e.telegraph.name),roomId+' warned captain skill');e.telegraph=null;e.sequence=[];e.hp=e.maxHp*(profile.phase.threshold-.02);assert(c.triggerCaptainPhase(e),roomId+' unique low-health mechanic');assert(e.captainPhase);const restored=Campaign.restore(c.snapshot());const re=restored.zone().enemies.find(x=>x.id===e.id);assert(re.roomCaptain&&re.captainMentor===mentor,roomId+' identity survives reload');}});
test('Supply-room captains terminate ordinary kill streaks and cannot seed Ringleaders',()=>{const c=fresh();c.enter('supply-vale');const z=c.zone(),regular=z.enemies.find(e=>e.roomGuard&&!e.roomCaptain),captain=z.enemies.find(e=>e.roomCaptain);regular.heroParticipated=true;regular.hp=0;c.kill(regular);assert.equal(c.s.streak.count,1);captain.heroParticipated=false;captain.hp=0;c.kill(captain);assert.equal(c.s.streak.count,0);assert(!c.s.pending.goblin,'captain does not seed a goblin ringleader');});
test('Frontier has a roaming Ashen Warlord disciple captain who patrols and enforces Mandatory Overtime',()=>{const c=fresh(.41);c.enter('frontier');const z=c.zone(),e=z.enemies.find(x=>x.fieldCaptain&&x.hp>0),profile=Campaign.rules.roomCaptains['frontier-overseer'];assert(e,'Frontier captain exists');assert(e.captain&&e.fieldCaptain);assert.equal(e.species,'orc');assert.equal(e.captainMentor,'warlord');assert.equal(e.name,'Ashen Quota Captain');assert(e.visualScale>1&&e.visualScale<=1.25);assert.equal(Visuals.height({...e,renderKind:'enemy'}),68);const i=c.regionIndex(),regional=Campaign.rules.ordinaryMeleeScaling[i];assert.equal(e.baseHp,Math.round((65+i*105)*regional.hp*2));assert.equal(e.baseDamage,Math.round((7+i*8)*regional.damage*1.25));assert.equal(c.enemyReward(e).xp,e.xp,'captain keeps miniboss XP instead of ordinary-mob halving');const bossKinds=new Set(Campaign.rules.attacks.warlord.map(a=>a.kind)),captainKinds=new Set(profile.attacks.map(a=>a.kind));assert([...captainKinds].filter(k=>bossKinds.has(k)).length>=2);const bossNames=new Set(c.boss('warlord').attacks.map(x=>x.split(':')[0].trim()));assert(profile.attacks.every(a=>!bossNames.has(a.name)),'Warlord ideas are translated rather than copied');e.captainPatrolWait=0;e.captainPatrolIndex=1;const before={x:e.x,y:e.y};for(let n=0;n<30;n++)c.updateCaptainPatrol(e,.1);assert(Math.hypot(e.x-before.x,e.y-before.y)>10,'captain actually wanders his inspection route');const pool=z.enemies.filter(x=>x!==e&&x.type==='mob'&&!x.captain&&!x.roomCaptain&&!x.summon&&x.hp>0).slice(0,8),workers=pool.slice(0,7),outsider=pool[7];for(const u of z.enemies)if(u!==e&&!pool.includes(u)&&u.type==='mob')u.hp=0;for(const [n,u]of workers.entries()){const radius=180+n*105,angle=n*.7;Object.assign(u,{x:e.x+Math.cos(angle)*radius,y:e.y+Math.sin(angle)*radius,home:{x:e.x+Math.cos(angle)*radius,y:e.y+Math.sin(angle)*radius},aggro:false,quotaOvertime:0});}if(outsider)Object.assign(outsider,{x:e.x+980,y:e.y,home:{x:e.x+980,y:e.y},aggro:false,quotaOvertime:0});Object.assign(c.hero,{x:e.x+110,y:e.y+20,maxHp:100000,hp:100000,armor:500});c.engage(e);e.hp=e.maxHp*(profile.phase.threshold-.02);assert(c.triggerCaptainPhase(e));assert(workers.every(u=>u.quotaOvertime>0&&u.aggro),'Mandatory Overtime mobilizes a distant chunk of nearby troops');assert(workers.some(u=>Math.hypot(u.x-e.x,u.y-e.y)>700),'pull includes genuinely distant patrols');if(outsider)assert.equal(outsider.quotaOvertime,0,'quota sweep does not conscript the whole region');const far=workers.at(-1),beforeFar=Math.hypot(far.x-c.hero.x,far.y-c.hero.y);for(let n=0;n<20;n++)c.updateEnemies(.1);assert(Math.hypot(far.x-c.hero.x,far.y-c.hero.y)<beforeFar,'conscripted distant mob actually advances toward the hero');assert.equal(e.captainPhase,true);const raw=c.snapshot(),restored=Campaign.restore(raw),re=restored.zone().enemies.find(x=>x.id===e.id);assert(re.fieldCaptain&&re.captain&&re.captainMentor==='warlord');const hp=re.baseHp;restored.zone();restored.authoredPlaces(restored.zone());assert.equal(re.baseHp,hp,'zone refresh never reapplies regional scaling to captain');});
test('The roaming Frontier captain breaks ordinary kill streaks and respawns as the same miniboss',()=>{const c=fresh();c.enter('frontier');const z=c.zone(),regular=z.enemies.find(e=>e.type==='mob'&&!e.captain&&!e.guard&&e.form==='normal'&&e.hp>0),captain=z.enemies.find(e=>e.fieldCaptain);regular.heroParticipated=true;regular.hp=0;c.kill(regular);assert.equal(c.s.streak.count,1);captain.heroParticipated=false;captain.hp=0;c.kill(captain);assert.equal(c.s.streak.count,0);assert(!c.s.pending.orc,'captain cannot seed an Orc ringleader');Object.assign(c.hero,{x:300,y:350});for(let n=0;n<620;n++)c.updatePacks(.1);assert(captain.hp>0&&captain.fieldCaptain&&captain.name==='Ashen Quota Captain','quota inspector returns to work');assert.equal(captain.captainPhase,false);});
test('Critical notice channel is reserved for major progression events',()=>{const c=fresh();assert.equal(c.notices.length,0);c.say('routine');assert.equal(c.notices.length,0);c.xp(120);assert(c.notices.at(-1).text.includes('Talent point'));assert(c.notices.at(-1).duration>=5);const e=boss(c,'thorn');slay(c,e);c.updateEnemies(121);slay(c,e);assert(c.notices.at(-1).text.includes('TRUE will emerge'));assert(c.notices.at(-1).duration>=5);c.updateElites(5.1);assert(c.notices.at(-1).text.includes('TRUE has appeared'));assert(c.notices.at(-1).duration>=6);});
test('MP progression uses the smaller level curve and repairs oversized existing saves',()=>{for(const id of Object.keys(Campaign.classes)){const c=new Campaign('normal',id);const base=Campaign.classes[id].mp;for(let n=1;n<16;n++)c.xp(120*c.hero.level);assert.equal(c.hero.level,16);assert.equal(c.hero.maxMp,base+75,id+' level-16 max MP');const old=c.snapshot(),ratio=.4;delete old.manaBalanceVersion;old.hero.maxMp=base+15*15;old.hero.mp=old.hero.maxMp*ratio;const r=Campaign.restore(old);assert.equal(r.hero.maxMp,base+75,id+' repaired max MP');assert(Math.abs(r.hero.mp-r.hero.maxMp*ratio)<1e-9,id+' preserves MP percentage');assert.equal(r.s.manaBalanceVersion,1);}});
test('MP regenerates slowly in combat, faster outside combat, and mana talent scaling is restrained',()=>{const c=fresh(),e=c.zone().enemies.find(e=>e.type==='mob');c.hero.mp=0;c.hero.potions.mana=0;c.hero.potions.greater_mana=0;c.s.party=[];assert.equal(c.manaRegenRate(),2.5);for(let i=0;i<10;i++)c.tick(.1);assert(Math.abs(c.hero.mp-2.5)<.01,'base out-of-combat regen');c.hero.mp=0;Object.assign(e,{x:c.hero.x+100,y:c.hero.y,home:{x:c.hero.x+100,y:c.hero.y},aggro:true,heroParticipated:true,damage:0,baseDamage:0,hp:999,maxHp:999,baseHp:999});c.zone().enemies=[e];assert.equal(c.manaRegenRate(),1);const updateEnemies=c.updateEnemies;c.updateEnemies=()=>{};for(let i=0;i<10;i++)c.tick(.1);assert(Math.abs(c.hero.mp-1)<.01,'base combat regen');c.hero.mp=0;c.hero.talents[1]=5;assert.equal(c.manaRegenRate(),2.25);for(let i=0;i<10;i++)c.tick(.1);assert(Math.abs(c.hero.mp-2.25)<.01,'max talent combat regen stays bounded');c.updateEnemies=updateEnemies;});
test('Higher skill ranks cost modestly more MP and Mage Recovery restores a bounded amount',()=>{const c=fresh(),e=c.zone().enemies.find(e=>e.type==='mob');Object.assign(c.hero,c.safe(e.x-50,e.y));c.hero.skills[1]=1;c.hero.mp=100;c.hero.cd[1]=0;assert.equal(c.skillManaCost(2,1),15);assert(c.cast(2,e.id));assert.equal(c.hero.mp,85);c.hero.skills[1]=8;c.hero.mp=100;c.hero.cd[1]=0;e.hp=e.maxHp;assert.equal(c.skillManaCost(2,8),24);assert(c.cast(2,e.id));assert.equal(c.hero.mp,76);const m=new Campaign('normal','mage');m.hero.skills[2]=8;m.hero.mp=0;m.hero.cd[2]=0;assert(m.cast(3));assert.equal(m.hero.mp,43);});
test('Only authored magical pressure drains MP; physical damage leaves MP unchanged',()=>{const c=fresh();c.hero.mp=c.hero.maxMp;const before=c.hero.mp;c.hitParty(c.hero,20);assert.equal(c.hero.mp,before,'physical hit does not drain MP');c.enter('march');c.s.clock=500;c.updateNight();const w=c.zone().enemies.find(e=>e.species==='wraith'&&e.nightOnly);c.s.party=[];Object.assign(c.hero,c.safe(w.x+80,w.y));c.hero.hp=10000;c.hero.maxHp=10000;c.hero.mp=c.hero.maxMp;c.startNightSkill(w,c.hero);w.telegraph.timer=0;const wBefore=c.hero.mp;c.resolveAttack(w);assert(c.hero.mp<wBefore,'Soul Drain consumes MP');c.enter('crown');const d=boss(c,'darklord');c.s.party=[];Object.assign(c.hero,c.safe(d.x+80,d.y));c.hero.hp=10000;c.hero.maxHp=10000;c.hero.mp=c.hero.maxMp;d.attackIndex=3;c.startAttack(d,c.hero,3);const dBefore=c.hero.mp;c.resolveAttack(d);assert(c.hero.mp<dBefore,'Dark Lord magical attack consumes MP');});
test('Idle hostile monsters wander locally without moving their authored spawn points',()=>{const scenarios=[
 c=>c.zone().enemies.find(e=>e.type==='mob'&&!e.guard&&!e.ranged&&!e.captain&&e.hp>0),
 c=>c.zone().enemies.find(e=>e.type==='boss'&&e.hp>0),
 c=>{c.enter('crypt');return c.zone().enemies.find(e=>e.guard&&e.hp>0);},
 c=>{c.enter('supply-vale');return c.zone().enemies.find(e=>e.roomCaptain&&e.hp>0);},
 c=>{c.enter('march');c.s.clock=500;c.updateNight();return c.zone().enemies.find(e=>e.nightOnly&&e.hp>0);}
];for(const getEnemy of scenarios){const c=fresh(),e=getEnemy(c);assert(e,'wander sample exists');const profile=c.idleWanderProfile(e),home={...e.home};assert(profile&&profile.radius>0);e.idleWanderWait=0;let target=null;for(let n=0;n<24&&!target;n++){const angle=n*Math.PI/12,candidate={x:home.x+Math.cos(angle)*profile.radius*.6,y:home.y+Math.sin(angle)*profile.radius*.6};if(!c.blocked(candidate.x,candidate.y,c.zoneId,12)&&c.clearSegment(e,candidate,12))target=candidate;}assert(target,e.name+' has a reachable local wander target');e.idleWanderTarget=target;const before={x:e.x,y:e.y};for(let n=0;n<20;n++)c.updateIdleWander(e,.1);assert(Math.hypot(e.x-before.x,e.y-before.y)>1,e.name+' moves while idle');assert.deepEqual(e.home,home,e.name+' authored home stays fixed');assert(Math.hypot(e.x-home.x,e.y-home.y)<=profile.radius+2,e.name+' stays in local wander radius');c.engage(e);assert.equal(e.idleWanderTarget,undefined,e.name+' stops wandering on engagement');e.aggro=false;e.idleWanderTarget={x:home.x+5,y:home.y};const snap=c.snapshot(),saved=snap.zones[c.zoneId].enemies.find(x=>x.id===e.id);assert(saved);assert.equal(saved.x,home.x);assert.equal(saved.y,home.y);assert.equal(saved.idleWanderTarget,undefined);}});
test('Every hostile archetype has a bounded idle-wander profile while the Frontier overseer keeps his inspection route',()=>{const c=fresh(),R=Campaign.rules;for(const key of ['ordinary','ranged','guardian','captain','ringleader','boss','night','summon']){const p=R.idleWander[key];assert(p&&p.radius>=20&&p.radius<=60,key+' bounded wander radius');assert(p.speed>0&&p.minPause>0&&p.maxPause>p.minPause,key+' paced idle movement');}c.enter('frontier');const overseer=c.zone().enemies.find(e=>e.fieldCaptain);assert(overseer);assert.equal(c.idleWanderProfile(overseer),null,'roaming overseer uses his larger authored patrol instead');});
test('Normal world cycle is six minutes of day and four minutes of night',()=>{const c=fresh();c.s.clock=359.9;assert(!c.night());c.tick(.2);assert(c.night());c.s.clock=599.9;c.tick(.2);assert(!c.night());assert(c.s.clock<1);});
test('Night enemies are strong and use distinct warned abilities',()=>{for(const [zone,species,name] of [['march','wraith','Soul Drain'],['frontier','stalker','Shadow Pounce']]){const c=fresh();c.enter(zone);c.s.clock=500;c.updateNight();const e=c.zone().enemies.find(e=>e.species===species&&e.nightOnly),cfg=Campaign.rules.nightEnemyCombat[species];assert(e);const i=c.regionIndex();assert.equal(e.baseHp,Math.round((120+i*100)*cfg.hp));assert.equal(e.baseDamage,Math.round((12+i*7)*cfg.damage));c.s.party=[];Object.assign(c.hero,{x:e.x+100,y:e.y,maxHp:10000,hp:10000});c.engage(e);e.specialCd=0;c.updateEnemies(.1);assert.equal(e.telegraph?.name,name);if(species==='wraith'){e.hp=e.maxHp*.5;const hp=c.hero.hp;e.telegraph.timer=0;c.updateEnemies(.1);assert(c.hero.hp<hp);assert(c.hero.slow>0);assert(e.hp>e.maxHp*.5);}else{e.telegraph.timer=0;c.updateEnemies(.1);assert(e.motion);assert.equal(e.motion.speed,cfg.pounceSpeed);}}});
test('Every normal boss can summon three regional adds with scaled threat and zero rewards',()=>{for(const b of D.bosses){const c=fresh(),e=boss(c,b.id),index=Campaign.rules.attacks[b.id].findIndex(a=>a.kind==='summon');assert(index>=0,b.id+' summon mechanic');c.zone().enemies=[e];c.s.party=[];Object.assign(c.hero,c.safe(e.x+180,e.y));c.startAttack(e,c.hero,index);assert.equal(e.telegraph.kind,'summon',b.id);c.resolveAttack(e);const adds=c.zone().enemies.filter(x=>x.summon&&x.owner===e.id&&x.hp>0),cfg=Campaign.rules.summonScaling[c.regionIndex()],plan=Campaign.rules.attacks[b.id][index];assert.equal(adds.length,b.id==='warlord'?4:3,b.id+' normal summon count');for(const a of adds){assert.equal(a.baseHp,Math.round((40+e.level*15)*cfg.hp*(plan.normalHpScale||1)),b.id+' summon hp');assert.equal(a.baseDamage,Math.round((5+e.level)*cfg.damage*(plan.normalDamageScale||1)),b.id+' summon damage');assert.equal(a.gold,0);assert.equal(a.xp,0);assert.equal(a.summonBalanceVersion,1);}}});
test('TRUE bosses enter with their authored elite warband size and two ringleader captains',()=>{for(const b of D.bosses){const c=fresh(),e=boss(c,b.id,'true');c.zone().enemies=[e];c.s.party=[];Object.assign(c.hero,c.safe(e.x+350,e.y));c.engage(e);const adds=c.zone().enemies.filter(u=>u.summon&&u.owner===e.id&&u.hp>0),minions=adds.filter(u=>u.trueSummonRole==='minion'),captains=adds.filter(u=>u.trueSummonRole==='captain');const warband=b.id==='warlord'?{total:8,minions:6,captains:2}:{total:6,minions:4,captains:2};assert.equal(adds.length,warband.total,b.id+' TRUE warband size');assert.equal(minions.length,warband.minions,b.id+' enhanced minion count');assert.equal(captains.length,warband.captains,b.id+' ringleader captain count');assert(minions.every(u=>u.form==='normal'&&u.trueSummon&&u.gold===0&&u.xp===0&&u.level===e.level&&u.name.startsWith('TRUE-bound ')),b.id+' enhanced minion identity');assert(captains.every(u=>u.form==='ringleader'&&u.ringleaderHealthVersion===3&&u.trueSummon&&u.gold===0&&u.xp===0&&u.level===e.level&&/ Ringleader$/.test(u.name)),b.id+' captain ringleader identity');assert(captains.every(u=>u.baseHp>minions[0].baseHp&&u.baseDamage>minions[0].baseDamage),b.id+' captains outrank minions');}});
test('Legacy generic TRUE warbands normalize to four minions and two captains on engagement',()=>{const c=fresh(),e=boss(c,'thorn','true');c.zone().enemies=[e];for(let i=0;i<6;i++){const s=c.makeEnemy({species:'wolf',name:'TRUE Den pup',level:e.level,hp:100,damage:10,gold:0,xp:0},{x:e.x+80+i*20,y:e.y+100});s.summon=true;s.owner=e.id;s.trueSummon=true;c.zone().enemies.push(s);}e.trueEntourageSpawned=true;c.s.party=[];Object.assign(c.hero,c.safe(e.x+350,e.y));c.engage(e);const adds=c.zone().enemies.filter(u=>u.summon&&u.owner===e.id&&u.hp>0);assert.equal(adds.length,6);assert.equal(adds.filter(u=>u.trueSummonRole==='minion').length,4);assert.equal(adds.filter(u=>u.trueSummonRole==='captain').length,2);});
test('TRUE summon actions replenish each boss to its authored warband cap',()=>{for(const b of D.bosses){const c=fresh(),e=boss(c,b.id,'true'),index=Campaign.rules.attacks[b.id].findIndex(a=>a.kind==='summon');assert(index>=0,b.id+' TRUE summon mechanic');c.zone().enemies=[e];c.s.party=[];Object.assign(c.hero,c.safe(e.x+350,e.y));c.engage(e);let adds=c.zone().enemies.filter(u=>u.summon&&u.owner===e.id&&u.hp>0);adds.filter(u=>u.trueSummonRole==='minion').slice(0,3).forEach(u=>{u.hp=0;c.kill(u);});adds.filter(u=>u.trueSummonRole==='captain').slice(0,1).forEach(u=>{u.hp=0;c.kill(u);});e.summonCd=0;c.startAttack(e,c.hero,index);assert.equal(e.telegraph.kind,'summon',b.id);c.resolveAttack(e);adds=c.zone().enemies.filter(u=>u.summon&&u.owner===e.id&&u.hp>0);const warband=b.id==='warlord'?{total:8,minions:6,captains:2}:{total:6,minions:4,captains:2};assert.equal(adds.length,warband.total,b.id+' TRUE summon hard cap');assert.equal(adds.filter(u=>u.trueSummonRole==='minion').length,warband.minions,b.id+' minion refill');assert.equal(adds.filter(u=>u.trueSummonRole==='captain').length,warband.captains,b.id+' captain refill');}});
test('Ashen Warlord is the summon-count exception: four normal guards and a six-plus-two TRUE warband',()=>{const c=fresh(),normal=boss(c,'warlord'),index=Campaign.rules.attacks.warlord.findIndex(a=>a.kind==='summon');c.zone().enemies=[normal];c.s.party=[];Object.assign(c.hero,c.safe(normal.x+180,normal.y));c.startAttack(normal,c.hero,index);c.resolveAttack(normal);assert.equal(c.bossOwnedSummons(normal).length,4);const t=c.bossEnemy(c.boss('warlord'),'true',{x:normal.x,y:normal.y});c.zone().enemies=[t];c.engage(t);let adds=c.bossOwnedSummons(t);assert.equal(adds.length,8);assert.equal(adds.filter(u=>u.trueSummonRole==='minion').length,6);assert.equal(adds.filter(u=>u.trueSummonRole==='captain').length,2);});
test('Stone Colossus and Ash Sentinel TRUE forms still force a four-plus-two half-health refill',()=>{for(const id of ['mine','citadel']){const c=fresh(),e=boss(c,id,'true');c.zone().enemies=[e];c.s.party=[];Object.assign(c.hero,c.safe(e.x+350,e.y));c.engage(e);let adds=c.zone().enemies.filter(u=>u.summon&&u.owner===e.id&&u.hp>0);adds.filter(u=>u.trueSummonRole==='minion').slice(0,3).forEach(u=>{u.hp=0;c.kill(u);});adds.filter(u=>u.trueSummonRole==='captain').slice(0,1).forEach(u=>{u.hp=0;c.kill(u);});e.hp=e.maxHp*.49;c.updateEnemies(.1);adds=c.zone().enemies.filter(u=>u.summon&&u.owner===e.id&&u.hp>0);assert.equal(adds.filter(u=>u.trueSummonRole==='minion').length,4,id+' minion refill');assert.equal(adds.filter(u=>u.trueSummonRole==='captain').length,2,id+' captain refill');assert(e.trueHalfSummonWave);}});
test('TRUE ringleader captains use normal ringleader Frenzy behavior',()=>{const c=fresh(),e=boss(c,'thorn','true');c.zone().enemies=[e];c.s.party=[];Object.assign(c.hero,c.safe(e.x+350,e.y));c.engage(e);const captain=c.zone().enemies.find(u=>u.trueSummonRole==='captain');assert(captain&&captain.form==='ringleader');captain.hp=captain.maxHp*.49;captain.cd=1;c.updateEnemies(.1);assert(captain.frenzy);assert(captain.cd<=.2);});
test('Every boss exposes all authored warned mechanics, including universal summon actions',()=>{const c=fresh();for(const b of D.bosses){const e=boss(c,b.id),plans=Campaign.rules.attacks[b.id],names=[];assert(plans.length>=4,b.id+' mechanic count');assert(plans.some(a=>a.kind==='summon'),b.id+' has summon mechanic');for(let i=0;i<plans.length;i++){e.hp=e.maxHp;c.startAttack(e,c.hero,i);names.push(e.telegraph.name);assert(e.telegraph.total>=.8,b.id+' warning '+i);}assert.equal(new Set(names).size,plans.length,b.id+' unique mechanic names');}});
test('Boss decision weights react to range, depleted summons, phases and never repeat the last move',()=>{const c=fresh(),r=boss(c,'ridge');c.zone().enemies=[r];const close={x:r.x+90,y:r.y},far={x:r.x+340,y:r.y};let a=c.bossAttackWeights(r,close),b=c.bossAttackWeights(r,far);assert(a[0]>b[0],'Ridge hammer favored nearby');assert(b[2]>a[2],'Ridge charge favored at range');const summon=Campaign.rules.attacks.ridge.findIndex(x=>x.kind==='summon');assert(a[summon]>Math.max(a[0],a[1],a[2]),'empty warband strongly favors summon pressure');r.summonCd=5;assert.equal(c.bossAttackWeights(r,close)[summon],0,'summon cooldown prevents spam');r.summonCd=0;r.lastAttackIndex=1;assert.equal(c.bossAttackWeights(r,far)[1],0,'boss never immediately repeats a mechanic');const d=boss(c,'darklord');c.zone().enemies=[d];d.hp=d.maxHp*.8;assert.equal(c.bossAttackWeights(d,c.hero)[3],0,'Crown phase locked above half health');d.hp=d.maxHp*.4;assert(c.bossAttackWeights(d,c.hero)[3]>0,'Crown phase unlocked below half health');});
test('Late boss control mechanics can explicitly pressure the hero through companion screens',()=>{const c=fresh(),e=boss(c,'ridge');c.zone().enemies=[e];const ally=c.unit('soldier',e.x+50,e.y);c.s.party=[ally];Object.assign(c.hero,c.safe(e.x+300,e.y));c.startAttack(e,ally,1);assert.equal(e.telegraph.x,c.hero.x);assert.equal(e.telegraph.y,c.hero.y);});
test('Low-health boss combos chain existing readable mechanics instead of only adding stats',()=>{for(const [family,behavior]of Object.entries(Campaign.rules.bossBehavior)){for(const combo of behavior.combos||[]){const c=new Campaign('normal','paladin',()=>0),e=boss(c,family);c.zone().enemies=[e];c.s.party=[];Object.assign(c.hero,c.safe(e.x+170,e.y));e.hp=e.maxHp*(combo.phase==='high'?.8:.4);e.summonCd=0;c.startAttack(e,c.hero,combo.from);assert(e.sequence.some(a=>a.index===combo.to),family+' combo '+combo.from+'→'+combo.to);}}});
test('Unreachable aggression resets after twelve seconds and ignores player damage as progress',()=>{const c=fresh(),e=c.zone().enemies.find(e=>e.type==='mob');c.s.party=[];Object.assign(c.hero,{x:e.x+330,y:e.y});c.engage(e);e.hp-=20;c.follow=()=>false;for(let i=0;i<119;i++)c.updateEnemies(.1);assert(e.aggro);for(let i=0;i<22;i++)c.updateEnemies(.1);assert.equal(e.hp,e.baseHp);assert(!e.aggro);assert.deepEqual({x:e.x,y:e.y},e.home);});
test('Field TRUE progress is per boss and ordinary kills cannot reset it',()=>{const c=fresh(),e=boss(c,'thorn');slay(c,e);assert.equal(c.s.fieldBossKills.thorn,1);c.updateEnemies(121);const mob=c.zone().enemies.find(x=>x.type==='mob'&&x.hp>0);slay(c,mob,true);assert.equal(c.s.fieldBossKills.thorn,1);slay(c,e);assert.equal(c.s.fieldBossKills.thorn,2);assert(c.s.pending.thorn&&c.s.pending.thorn.kind==='field');});
test('Existing saves reconstruct field-boss TRUE entitlement, including one-kill Dark Lord',()=>{const c=fresh();c.s.normal.thorn=true;c.s.keys.thorn=true;c.s.normal.darklord=true;c.s.keys.darklord=true;c.s.statistics.events.push({time:10,type:'bossDefeat',family:'thorn',form:'normal'},{time:140,type:'bossDefeat',family:'thorn',form:'normal'},{time:300,type:'bossDefeat',family:'darklord',form:'normal'});delete c.s.fieldBossKills;delete c.s.pending.thorn;delete c.s.pending.darklord;const r=Campaign.restore(c.snapshot());assert.equal(r.s.fieldBossKills.thorn,2);assert(r.s.pending.thorn&&r.s.pending.thorn.kind==='field');assert.equal(r.s.fieldBossKills.darklord,1);assert(r.s.pending.darklord&&r.s.pending.darklord.kind==='field');assert.equal(r.s.pending.darklord.delay,5);});
test('Field normal respawns after 120 seconds, but second kill spawns its identified TRUE remotely after 5 seconds',()=>{const c=fresh(),e=boss(c,'thorn'),home={...e.home};slay(c,e);assert.equal(e.respawn,120);c.updateEnemies(121);assert(e.hp>0);slay(c,e);assert.equal(c.s.pending.thorn.count,1);assert.equal(c.s.pending.thorn.delay,5);assert.equal(e.respawn,0);c.updateElites(4.9);assert(!c.zone().enemies.some(e=>e.family==='thorn'&&e.form==='true'&&e.hp>0));c.updateElites(.2);const t=c.zone().enemies.find(e=>e.family==='thorn'&&e.form==='true'&&e.hp>0);assert(t);assert.equal(t.type,'boss');assert.equal(t.form,'true');assert.match(t.name,/ TRUE$/);assert.notEqual(t.name,e.name);assert(Math.hypot(t.x-home.x,t.y-home.y)>=650);slay(c,t);c.updateElites(1);c.s.normal.darklord=true;c.s.true.darklord=true;c.s.victories['darklord:normal']=true;c.s.victories['darklord:true']=true;c.awaken();c.updateEnemies(121);assert(c.zone().enemies.some(e=>e.family==='thorn'&&e.hp>0));});
test('Ordinary field bosses still require two normal defeats before the remote TRUE spawn',()=>{for(const b of D.bosses.filter(b=>b.kind==='field'&&b.id!=='darklord')){const c=fresh(),e=boss(c,b.id),home={...e.home};slay(c,e);assert.equal(e.respawn,120,b.id+' first normal respawn');assert(!c.s.pending[b.id],b.id+' does not queue TRUE on first defeat');c.updateEnemies(121);assert(e.hp>0,b.id+' normal returns for second fight');slay(c,e);const p=c.s.pending[b.id];assert(p&&p.kind==='field',b.id+' queues TRUE');assert.equal(p.delay,5,b.id+' TRUE delay');assert.equal(e.respawn,0,b.id+' normal respawn cancelled');c.updateElites(4.9);assert(!c.zone().enemies.some(x=>x.family===b.id&&x.form==='true'&&x.hp>0),b.id+' TRUE does not appear early');c.updateElites(.2);const t=c.zone().enemies.find(x=>x.family===b.id&&x.form==='true'&&x.hp>0);assert(t,b.id+' TRUE appears after 5 seconds');assert.match(t.name,/ TRUE$/);assert(Math.hypot(t.x-home.x,t.y-home.y)>=650,b.id+' TRUE relocates away from original boss home');assert(Math.hypot(t.x-c.hero.x,t.y-c.hero.y)>=380,b.id+' TRUE does not spawn on the hero');}});
test('The first normal Dark Lord defeat immediately queues Dark Lord TRUE after five seconds',()=>{const c=fresh(),e=boss(c,'darklord'),home={...e.home};slay(c,e);assert.equal(c.s.fieldBossKills.darklord,1);assert(c.s.pending.darklord&&c.s.pending.darklord.kind==='field');assert.equal(c.s.pending.darklord.delay,5);assert.equal(e.respawn,0,'normal Dark Lord does not return for a second normal fight');c.updateElites(4.9);assert(!c.zone().enemies.some(x=>x.family==='darklord'&&x.form==='true'&&x.hp>0));c.updateElites(.2);const t=c.zone().enemies.find(x=>x.family==='darklord'&&x.form==='true'&&x.hp>0);assert(t);assert(Math.hypot(t.x-home.x,t.y-home.y)>=650);assert.match(t.name,/ TRUE$/);});
test('Dungeon one-third roll is saved, grants an early TRUE at most once and never respawns normal',()=>{const c=fresh(.2);slay(c,boss(c,'crypt'));assert(c.s.earlyRoll.crypt);c.activatePending();const t=c.zone().enemies.find(e=>e.form==='true'&&e.hp>0);assert(t);slay(c,t);c.enter('vale');c.enter('crypt');assert(!c.zone().enemies.some(e=>e.type==='boss'&&e.hp>0));const restored=Campaign.restore(c.snapshot(),()=>.9);assert(restored.s.earlyRoll.crypt);});
test('Awakening guarantees missed TRUEs, normalizes the common band and retains early victories',()=>{const c=fresh();slay(c,boss(c,'crypt'));assert.equal(c.s.earlyRoll.crypt,false);c.victory('archive','normal');c.victory('archive','true');slay(c,boss(c,'darklord'));slay(c,boss(c,'darklord','true'));assert.equal(c.s.phase,'awakening');assert(c.s.pending.crypt);assert(!c.s.pending.archive);c.enter('crypt');const e=c.zone().enemies.find(e=>e.form==='true'&&e.hp>0);assert.equal(e.baseHp,13000);assert.equal(e.baseDamage,70);assert.equal(e.level,c.s.awakeningLevel);});
test('Skipped normal dungeon defeated after awakening guarantees TRUE despite a failed roll',()=>{const c=fresh();slay(c,boss(c,'darklord'));slay(c,boss(c,'darklord','true'));slay(c,boss(c,'mine'));assert.equal(c.s.earlyRoll.mine,false);assert(c.s.pending.mine);c.activatePending();assert(c.zone().enemies.some(e=>e.form==='true'&&e.hp>0));});
test('Night first victories deduplicate; Normal caps at fifteen while Nightmare counts twenty',()=>{for(const mode of ['normal','nightmare']){const c=new Campaign(mode);c.s.clock=500;for(const b of D.bosses)c.victory(b.id,'normal');assert.equal(c.nightPoints(),10);c.s.phase='awakening';for(const b of D.bosses)c.victory(b.id,'true');assert.equal(c.nightPoints(),mode==='normal'?15:20);const m=c.multipliers();assert(Math.abs(m.hp-(mode==='normal'?1.55:1.7))<1e-10);c.victory('crypt','true');assert.equal(c.nightPoints(),mode==='normal'?15:20);}});
test('Peace is reachable in both modes, includes 60 native residents, 20 dungeon residents and four neutral field bosses',()=>{for(const mode of ['normal','nightmare']){const c=new Campaign(mode);for(const r of D.regions)c.enter(r.id);for(const id of Campaign.dungeonIds)c.enter(id);for(const b of D.bosses)c.victory(b.id,'normal');c.victory('darklord','true');c.awaken();for(const id of Campaign.dungeonIds)c.victory(id,'true');c.checkEnding();assert(c.peace);let out=0,inside=0,field=0;for(const z of Object.values(c.s.zones)){for(const e of z.enemies){assert(e.neutral);assert.equal(c.damage(e,100),false);if(e.type==='boss')field++;else if(Campaign.dungeonIds.includes(z.id))inside++;else out++;}}assert.equal(out,60);assert.equal(inside,20);assert.equal(field,4);assert.equal(c.traps().length,0);assert(!c.cast(1));assert.equal(c.hitParty(c.hero,999),false);Campaign.restore(c.snapshot());if(mode==='nightmare'){assert.equal(c.s.clock,360);c.s.clock=599.95;c.tick(.1);assert(!c.night());}}});
test('All early TRUE clears allow immediate peace on TRUE Dark Lord; Dark Lord stays absent',()=>{const c=fresh();for(const id of Campaign.dungeonIds){c.victory(id,'normal');c.victory(id,'true');}slay(c,boss(c,'darklord'));slay(c,boss(c,'darklord','true'));assert(c.peace);c.enter('crown');assert(!c.zone().enemies.some(e=>e.family==='darklord'));});
test('All quests start active, complete automatically and pay without a board return',()=>{const c=fresh();assert.equal(Object.keys(c.s.quests).length,30);assert(Object.values(c.s.quests).every(q=>q.active&&!q.done&&!q.paid));const q0=c.questDefs().find(q=>q.id==='quest-0');slay(c,boss(c,'thorn'));c.rescue('thorn');for(const g of c.zone().enemies.filter(e=>e.mini==='field-thorn'))slay(c,g,false);assert(c.s.quests['quest-0'].done);assert(c.s.quests['quest-0'].paid);assert(!c.claim('quest-0'));const q5=c.questDefs().find(q=>q.id==='quest-5'),sites=[...q5.sites];for(const id of sites.slice(0,-1))c.discover(id);const gold=c.hero.gold;c.discover(sites.at(-1));assert(c.s.quests['quest-5'].done&&c.s.quests['quest-5'].paid);assert.equal(c.hero.gold,gold+q5.gold);for(const b of D.bosses)c.victory(b.id,'normal');for(const id of ['darklord',...Campaign.dungeonIds])c.victory(id,'true');c.checkEnding();assert(c.s.quests['quest-1'].closedByPeace);});
test('Paid travel preserves supplies and free return while death still applies the universal gold penalty',()=>{const c=fresh();assert(c.travel(1));assert.equal(c.s.zone,'march');assert.equal(c.hero.gold,5);assert(c.travel(-1));assert.equal(c.hero.gold,5);c.hero.gold=25;c.travel(1);c.die();c.enter('vale');assert(c.travel(1));assert.equal(c.hero.gold,0);});
test('Class defaults drive automatic field doctrine; manual switching unlocks at Expedition 3',()=>{for(const [cls,mode,label]of [['paladin','focus','TARGET'],['mage','guard','THREATS'],['ranger','guard','THREATS']]){const c=new Campaign('normal',cls,()=>.9),e=c.zone().enemies.find(e=>e.type==='mob'&&!e.ranged);Object.assign(c.hero,{x:e.x-100,y:e.y});Object.assign(e,{aggro:true,heroParticipated:true});assert.equal(c.squadDoctrineLabel().mode,mode,cls+' default doctrine');assert.equal(c.squadDoctrineLabel().label,label);assert(!c.toggleSquadDoctrine(),'Rank 1 keeps the automatic doctrine');c.s.expeditionRank=3;assert(c.toggleSquadDoctrine());assert.notEqual(c.s.squadDoctrine,mode);e.aggro=false;c.squadDoctrineLabel();assert.equal(c.s.squadDoctrine,mode,cls+' resets after disengagement');}});
test('Boss doctrine is BOSS for Paladin and ADDS for Mage/Ranger after Expedition 3',()=>{for(const [cls,mode,label]of [['paladin','focus','BOSS'],['mage','guard','ADDS'],['ranger','guard','ADDS']]){const c=new Campaign('normal',cls,()=>.9),b=c.zone().enemies.find(e=>e.type==='boss');c.s.expeditionRank=3;Object.assign(c.hero,{x:b.x-120,y:b.y});Object.assign(b,{aggro:true,heroParticipated:true});const state=c.squadDoctrineLabel();assert.equal(state.boss,true);assert.equal(state.mode,mode);assert.equal(state.label,label);assert(c.toggleSquadDoctrine());assert.equal(c.squadDoctrineLabel().label,label==='BOSS'?'ADDS':'BOSS');}});
test('Aggro near the hero defines an active encounter even before the hero attacks',()=>{const c=new Campaign('normal','mage',()=>.9),e=c.zone().enemies.find(e=>e.type==='mob');Object.assign(c.hero,{x:500,y:500});Object.assign(e,{x:620,y:500,aggro:true,heroParticipated:false});assert(c.squadDoctrineLabel().active,'nearby aggro activates the squad');e.x=1200;e.y=1200;assert(!c.squadDoctrineLabel().active,'far aggro does not hold the squad in combat');});
test('Expedition instructors train free ranks and higher rescued instructors can cover skipped earlier ranks',()=>{const c=fresh();assert.equal(c.s.expeditionRank,1);c.s.rescued.ridge=true;assert(c.trainExpedition('ridge'));assert(c.trainExpedition('ridge'));assert(c.trainExpedition('ridge'));assert.equal(c.s.expeditionRank,4);assert.equal(c.expeditionPartyCap(),4);assert(!c.trainExpedition('thorn'),'lower instructor cannot train above its ceiling');c.s.rescued.warlord=true;assert(c.trainExpedition('warlord'));c.s.rescued.citadel=true;assert(c.trainExpedition('citadel'));assert.equal(c.s.expeditionRank,6);assert.equal(c.expeditionPartyCap(),6);});
test('Shared Training follows all five instructors at 20/40/60/80/100 percent and updates applicable talent inheritance live',()=>{const c=fresh();c.hero.gold=10000;for(const id of ['thorn','mire','ridge','warlord','citadel'])c.s.rescued[id]=true;c.hero.talentPoints=4;c.talent(0);c.talent(0);c.talent(2);c.talent(2);const soldier=c.s.party.find(u=>u.type==='soldier'),base=soldier.maxHp,gold=c.hero.gold;assert.equal(c.heroTalentHpBonus(),60);assert.equal(c.heroTalentDamageBonus(),16);assert(c.trainExpeditionSupport('sharedTraining','thorn'));assert.equal(c.hero.gold,gold-280);assert.equal(c.expeditionSupportRank('sharedTraining'),1);assert.equal(soldier.maxHp,base+12);assert.equal(c.companionInheritedDamageBonus(),3);assert(!c.trainExpeditionSupport('sharedTraining','thorn'),'Mira stops at Rank 1');c.hero.talentPoints=3;c.talent(0);c.talent(2);c.talent(3);assert.equal(c.heroTalentHpBonus(),90);assert.equal(c.heroTalentDamageBonus(),24);assert.equal(c.heroTalentSpeedBonus(),40);assert.equal(soldier.maxHp,base+18);assert.equal(c.companionInheritedDamageBonus(),5);assert.equal(c.companionInheritedSpeedBonus(),8);for(const [family,rank]of [['mire',2],['ridge',3],['warlord',4],['citadel',5]]){const before=c.hero.gold;assert(c.trainExpeditionSupport('sharedTraining',family));assert.equal(c.hero.gold,before-280);assert.equal(c.expeditionSupportRank('sharedTraining'),rank);assert.equal(Math.round(c.expeditionSupportFraction('sharedTraining')*100),rank*20);}assert.equal(soldier.maxHp,base+90);assert.equal(c.companionInheritedDamageBonus(),24);assert.equal(c.companionInheritedSpeedBonus(),40);let movedSpeed=null;c.follow=(u,t,speed)=>{if(u===soldier)movedSpeed=speed;return true;};Object.assign(c.hero,{x:600,y:600});Object.assign(soldier,{x:100,y:600});c.s.party=[soldier];c.followPartyMember(soldier,[soldier],.1);assert.equal(movedSpeed,430,'100% Shared Training adds the full +40 movement talent bonus to the 390 catch-up pace');});
test('Later instructors can cover skipped Shared Training ranks one step at a time',()=>{const c=fresh();c.hero.gold=10000;c.s.rescued.citadel=true;for(let rank=1;rank<=5;rank++){assert(c.trainExpeditionSupport('sharedTraining','citadel'));assert.equal(c.expeditionSupportRank('sharedTraining'),rank);}assert(!c.trainExpeditionSupport('sharedTraining','citadel'));assert.equal(10000-c.hero.gold,1400);});
test('Shared Strength follows the smith ladder and inherits non-talent HP, damage and armor without double counting talents',()=>{const c=fresh();c.hero.gold=10000;c.s.rescued.crypt=true;c.hero.weapon=2;c.hero.reforges['weapon:2']=true;c.hero.armorTier=1;c.hero.reforges['armor:1']=true;c.hero.maxHp+=40;c.hero.hp+=40;c.hero.talentPoints=2;c.talent(0);c.talent(2);const soldier=c.s.party.find(u=>u.type==='soldier'),archer=c.s.party.find(u=>u.type==='archer'),natural=120+12*(c.hero.level-1);assert.equal(c.heroOtherHpBonus(),40);assert.equal(c.heroOtherDamageBonus(),40);assert.equal(c.heroEquipmentArmorBonus(),8);assert(c.trainExpeditionSupport('sharedStrength','crypt'));assert.equal(c.expeditionSupportRank('sharedStrength'),1);assert.equal(c.companionInheritedHpBonus(),10);assert.equal(c.companionInheritedDamageBonus(),10);assert.equal(c.companionInheritedArmorBonus(),2);assert.equal(c.companionArmor('soldier'),10);assert.equal(c.companionArmor('archer'),7);assert.equal(soldier.maxHp,natural+10);assert(!c.trainExpeditionSupport('sharedStrength','crypt'),'Borin stops at Rank 1');c.s.rescued.mine=true;assert(c.trainExpeditionSupport('sharedStrength','mine'));assert.equal(c.expeditionSupportRank('sharedStrength'),2);assert.equal(c.companionInheritedArmorBonus(),4);c.s.rescued.abyss=true;assert(c.trainExpeditionSupport('sharedStrength','abyss'));assert.equal(c.expeditionSupportRank('sharedStrength'),3);assert.equal(c.companionInheritedArmorBonus(),6);c.s.rescued.darklord=true;assert(c.trainExpeditionSupport('sharedStrength','darklord'));assert.equal(c.expeditionSupportRank('sharedStrength'),4);assert.equal(c.companionInheritedHpBonus(),40);assert.equal(c.companionInheritedDamageBonus(),40);assert.equal(c.companionInheritedArmorBonus(),8);assert.equal(c.companionArmor('soldier'),16);assert.equal(c.companionArmor('archer'),13);c.hero.armorTier=4;c.hero.reforges['armor:4']=true;assert.equal(c.heroEquipmentArmorBonus(),31);assert.equal(c.companionArmor('soldier'),39);assert.equal(c.companionArmor('archer'),36);});
test('A later equipment specialist can teach skipped Shared Strength ranks one step at a time',()=>{const c=fresh();c.hero.gold=10000;c.s.rescued.darklord=true;for(let rank=1;rank<=4;rank++){assert(c.trainExpeditionSupport('sharedStrength','darklord'));assert.equal(c.expeditionSupportRank('sharedStrength'),rank);}assert(!c.trainExpeditionSupport('sharedStrength','darklord'));assert.equal(10000-c.hero.gold,2100);});
test('Shared Strength smith ceilings are cumulative from Borin 1 through Vera 4',()=>{for(const [family,cap]of [['crypt',1],['mine',2],['abyss',3],['darklord',4]]){const c=fresh();c.hero.gold=10000;c.s.rescued[family]=true;for(let rank=1;rank<=cap;rank++){assert(c.trainExpeditionSupport('sharedStrength',family),family+' teaches rank '+rank);assert.equal(c.expeditionSupportRank('sharedStrength'),rank);}assert(!c.trainExpeditionSupport('sharedStrength',family),family+' stops at '+cap);}});
test('Inheritance skills keep their distinct rank counts and complete price ladders',()=>{const c=fresh();c.hero.gold=20000;c.s.rescued.citadel=true;c.s.rescued.darklord=true;for(const [id,family,costs]of [['sharedTraining','citadel',[280,280,280,280,280]],['sharedStrength','darklord',[250,400,600,850]]]){assert.equal(c.expeditionSupportRank(id),0,'zero is only the internal unlearned sentinel');assert.equal(c.expeditionSupportCost(id),costs[0]);for(let rank=1;rank<=costs.length;rank++){const before=c.hero.gold;assert(c.trainExpeditionSupport(id,family));assert.equal(c.expeditionSupportRank(id),rank);assert.equal(before-c.hero.gold,costs[rank-1]);assert.equal(c.expeditionSupportCost(id),rank<costs.length?costs[rank]:0);}assert(!c.trainExpeditionSupport(id,family));}});
test('Veteran, reserve and fallen companions all catch up when inheritance skills or hero bonuses improve',()=>{const c=fresh();c.hero.gold=10000;c.s.rescued.ridge=true;c.s.rescued.darklord=true;const veteran=c.s.party[0],reserve=c.unit('archer',0,0),fallen=c.unit('soldier',0,0);reserve.active=false;fallen.active=false;fallen.hp=0;c.s.party.push(reserve,fallen);const veteranBase=veteran.maxHp,reserveBase=reserve.maxHp,fallenBase=fallen.maxHp;c.hero.talentPoints=2;c.talent(0);c.talent(2);assert(c.trainExpeditionSupport('sharedTraining','ridge'));assert(veteran.maxHp>veteranBase);assert(reserve.maxHp>reserveBase);assert(fallen.maxHp>fallenBase);assert.equal(fallen.hp,0,'fallen veteran gains max HP but stays fallen');const beforeVeteran=veteran.maxHp,beforeReserve=reserve.maxHp;c.hero.talentPoints=1;c.talent(2);assert(veteran.maxHp>beforeVeteran);assert(reserve.maxHp>beforeReserve);c.hero.weapon=3;c.hero.reforges['weapon:3']=true;assert(c.trainExpeditionSupport('sharedStrength','darklord'));const inherited=c.companionInheritedDamageBonus();assert(inherited>0);assert.equal(veteran.damage,12,'stored role damage remains its base; inherited damage is applied live in combat');assert.equal(reserve.damage,15);const saved=c.snapshot(),restored=Campaign.restore(saved);assert.equal(restored.s.party.find(u=>u.id===veteran.id).maxHp,veteran.maxHp);assert.equal(restored.s.party.find(u=>u.id===reserve.id).maxHp,reserve.maxHp);assert.equal(restored.s.party.find(u=>u.id===fallen.id).hp,0);});
test('Neri trains repeatable Companion Vitality at 200g per +10 percent companion max HP without affecting hero HP',()=>{const c=fresh(),soldier=c.s.party.find(u=>u.type==='soldier'),archer=c.s.party.find(u=>u.type==='archer'),heroHp=c.hero.maxHp;assert(!c.trainCompanionVitality('archive'),'Neri must be rescued first');c.s.rescued.archive=true;c.hero.gold=10000;const reserve=c.unit('archer',0,0),fallen=c.unit('soldier',0,0);reserve.active=false;fallen.active=false;fallen.hp=0;c.s.party.push(reserve,fallen);for(let rank=1;rank<=11;rank++){const before=c.hero.gold;assert(c.trainCompanionVitality('archive'));assert.equal(c.companionVitalityRank(),rank);assert.equal(before-c.hero.gold,200);assert.equal(c.companionVitalityFraction(),rank*.1);}assert.equal(c.hero.maxHp,heroHp,'Companion Vitality never changes hero HP');assert.equal(soldier.maxHp,Math.round(120*2.1));assert.equal(archer.maxHp,Math.round(105*2.1));assert.equal(reserve.maxHp,Math.round(105*2.1));assert.equal(fallen.maxHp,Math.round(120*2.1));assert.equal(fallen.hp,0,'fallen companions gain max HP but stay fallen');assert(c.companionVitalityRank()>10,'training continues beyond +100 percent');});
test('Neri resets talents for 250g, refunds spent points and immediately removes Shared Training talent inheritance',()=>{const c=fresh();c.s.rescued.archive=true;c.s.expeditionSkills.sharedTraining=5;c.hero.gold=1000;c.hero.talentPoints=4;c.hero.weapon=2;c.hero.skills[1]=2;const baseHp=c.hero.maxHp,soldier=c.s.party.find(u=>u.type==='soldier');c.talent(0);c.talent(1);c.talent(2);c.talent(3);assert.deepEqual(c.hero.talents,[1,1,1,1]);assert.equal(c.heroTalentDamageBonus(),8);assert.equal(c.heroTalentHpBonus(),30);assert.equal(c.heroTalentSpeedBonus(),40);assert.equal(c.companionInheritedDamageBonus(),8);assert.equal(c.companionInheritedSpeedBonus(),40);assert(soldier.maxHp>120);const beforeSkill=c.hero.skills[1],beforeWeapon=c.hero.weapon;assert(c.resetTalents('archive'));assert.equal(c.hero.gold,750);assert.deepEqual(c.hero.talents,[0,0,0,0]);assert.equal(c.hero.talentPoints,4);assert.equal(c.hero.maxHp,baseHp);assert.equal(c.companionInheritedDamageBonus(),0);assert.equal(c.companionInheritedSpeedBonus(),0);assert.equal(soldier.maxHp,120);assert.equal(c.hero.skills[1],beforeSkill);assert.equal(c.hero.weapon,beforeWeapon);const gold=c.hero.gold;assert(!c.resetTalents('archive'),'no spent points means no charge');assert.equal(c.hero.gold,gold);});
test('Companion HP starts from Paladin/Ranger baselines while defense stays at the class baseline until Shared Strength',()=>{const c=fresh(),soldier=c.s.party.find(u=>u.type==='soldier'),archer=c.s.party.find(u=>u.type==='archer');assert.equal(soldier.maxHp,120);assert.equal(archer.maxHp,105);assert.equal(c.companionArmor('soldier'),8);assert.equal(c.companionArmor('archer'),5);c.hero.level=4;c.syncCompanionLevelStats();assert.equal(soldier.maxHp,156);assert.equal(archer.maxHp,141);assert.equal(c.companionArmor('soldier'),8);assert.equal(c.companionArmor('archer'),5);});
test('Old companions rescale to the new HP baseline on load while preserving wounds and fallen state',()=>{const c=fresh(),raw=c.snapshot(),soldier=raw.party.find(u=>u.type==='soldier'),archer=raw.party.find(u=>u.type==='archer');soldier.maxHp=152;soldier.hp=132;archer.maxHp=112;archer.hp=112;const fallen={...soldier,id:'legacy-fallen',hp:0,active:false};raw.party.push(fallen);const r=Campaign.restore(raw),rs=r.s.party.find(u=>u.id===soldier.id),ra=r.s.party.find(u=>u.id===archer.id),rf=r.s.party.find(u=>u.id==='legacy-fallen');assert.equal(rs.maxHp,120);assert.equal(rs.hp,100,'Soldier keeps 20 HP missing');assert.equal(ra.maxHp,105);assert.equal(ra.hp,105);assert.equal(rf.maxHp,120);assert.equal(rf.hp,0,'fallen veteran stays fallen');});
test('Old maxed Shared Training Rank 4 saves migrate once to new Rank 5 without losing 100 percent inheritance',()=>{const c=fresh(),raw=c.snapshot();raw.expeditionSkills.sharedTraining=4;delete raw.expeditionSupportVersion;const r=Campaign.restore(raw);assert.equal(r.expeditionSupportRank('sharedTraining'),5);assert.equal(r.expeditionSupportFraction('sharedTraining'),1);assert.equal(r.s.expeditionSupportVersion,2);const again=Campaign.restore(r.snapshot());assert.equal(again.expeditionSupportRank('sharedTraining'),5);});
test('Older saves without Companion Vitality load at rank zero',()=>{const c=fresh(),raw=c.snapshot();delete raw.companionVitalityRank;const r=Campaign.restore(raw);assert.equal(r.companionVitalityRank(),0);assert.equal(r.companionVitalityFraction(),0);});
test('Rank 1 basic barracks cost 20g; Rank 4 builds full for 120g and upgrades old basics for the remaining 100g',()=>{const c=fresh();c.hero.gold=1000;assert(c.build());const basic=c.zone().buildings.at(-1);assert.equal(c.hero.gold,980);assert.equal(basic.full,false);for(let i=0;i<50;i++)c.updateParty(.1);c.recallParty();c.s.recallActive=false;c.s.rescued.ridge=true;while(c.s.expeditionRank<4)c.trainExpedition('ridge');const before=c.hero.gold;assert(c.upgradeBarracks(basic.id));assert.equal(c.hero.gold,before-100);for(let i=0;i<50;i++)c.updateParty(.1);assert(basic.full);const prior=c.hero.gold;assert(c.build());const full=c.zone().buildings.at(-1);assert.equal(c.hero.gold,prior-120);assert.equal(full.full,true);});
test('Full barracks are resource deposits and manage active vs resting companions',()=>{const c=fresh();c.s.rescued.ridge=true;while(c.s.expeditionRank<4)c.trainExpedition('ridge');c.hero.gold=1000;assert(c.build());const b=c.zone().buildings.at(-1);for(let i=0;i<50;i++)c.updateParty(.1);const reserve=c.unit('soldier',0,0);reserve.active=false;c.s.party.push(reserve);assert(c.activateCompanion(reserve.id,b.id));assert.equal(c.activeParty().length,3);const active=c.activeParty()[0];assert(c.restCompanion(active.id));assert.equal(c.activeParty().length,2);Object.assign(reserve,{x:b.x+10,y:b.y+10,carry:5,order:{type:'deposit'}});assert.equal(c.depositSite(reserve).id,b.id);});
test('Soldiers screen pressure targets in THREATS and ADDS',()=>{const c=new Campaign('normal','mage',()=>.9),soldier=c.s.party.find(u=>u.type==='soldier'),archer=c.s.party.find(u=>u.type==='archer'),near=c.zone().enemies.find(e=>e.type==='mob'),far=c.zone().enemies.find(e=>e!==near&&e.type==='mob');Object.assign(c.hero,{x:500,y:500});Object.assign(archer,{x:520,y:490});Object.assign(soldier,{x:420,y:500,cd:0});Object.assign(near,{x:555,y:500,aggro:true,heroParticipated:false});Object.assign(far,{x:700,y:500,aggro:true,heroParticipated:false});c.s.squadDoctrine='guard';let chosen=null;const follow=c.follow.bind(c);c.follow=(u,t,...args)=>{if(u===soldier&&t.id)chosen=t;return follow(u,t,...args);};c.updateParty(.05);assert.equal(chosen?.id,near.id,'Soldier intercepts the threat pressing the hero/back line');});
test('Archers fall back toward formation when rushed and step forward only enough to shoot',()=>{const c=new Campaign('normal','mage',()=>.9),archer=c.s.party.find(u=>u.type==='archer'),e=c.zone().enemies.find(e=>e.type==='mob');c.s.party=[archer];Object.assign(c.hero,{x:500,y:500});Object.assign(archer,{x:500,y:480,cd:0});Object.assign(e,{x:500,y:520,aggro:true,heroParticipated:true});let destination=null;c.follow=(u,t)=>{if(u===archer)destination={x:t.x,y:t.y};return true;};c.updateParty(.05);assert(destination&&Math.hypot(destination.x-e.x,destination.y-e.y)>Math.hypot(archer.x-e.x,archer.y-e.y),'rushed Archer retreats toward the formation side');Object.assign(e,{x:500,y:900});destination=null;c.s.squadEngagement=null;c.updateParty(.05);assert(destination,'distant target makes Archer reposition');const shotRange=Math.hypot(destination.x-e.x,destination.y-e.y);assert(shotRange>=230&&shotRange<=280,'Archer advances only to useful firing distance');});
test('Class-aware formations keep the correct combat role closest to the hero',()=>{for(const cls of ['mage','ranger']){const c=new Campaign('normal',cls,()=>.9);c.s.party=[c.unit('soldier',0,0),c.unit('archer',0,0),c.unit('soldier',0,0),c.unit('archer',0,0)];c.formationHeading={x:0,y:1};const living=c.s.party,d=u=>Math.hypot(c.partyFollowPoint(u,living).x-c.hero.x,c.partyFollowPoint(u,living).y-c.hero.y),soldiers=living.filter(u=>u.type==='soldier'),archers=living.filter(u=>u.type==='archer');assert(Math.max(...archers.map(d))<Math.max(...soldiers.map(d)),cls+' keeps Archers in the close ranged pack');}const p=new Campaign('normal','paladin',()=>.9);p.s.party=[p.unit('archer',0,0),p.unit('soldier',0,0),p.unit('archer',0,0),p.unit('soldier',0,0)];p.formationHeading={x:0,y:1};const living=p.s.party,d=u=>Math.hypot(p.partyFollowPoint(u,living).x-p.hero.x,p.partyFollowPoint(u,living).y-p.hero.y),soldiers=living.filter(u=>u.type==='soldier'),archers=living.filter(u=>u.type==='archer');assert(Math.max(...soldiers.map(d))<Math.max(...archers.map(d)),'Paladin keeps Soldiers in the close melee pack');});
test('Formation orientation rotates with the hero movement direction',()=>{const c=new Campaign('normal','paladin',()=>.9),archer=c.s.party.find(u=>u.type==='archer');c.formationHeading={x:1,y:0};const p=c.partyFollowPoint(archer,c.s.party.filter(u=>u.hp>0));assert(p.x<c.hero.x,'Paladin Archer stays behind eastward travel');const x=c.hero.x;c.tick(.1,{x:1,y:0});assert(c.hero.x>x);assert(c.formationHeading.x>.9,'actual hero movement updates formation heading');});
test('Recall cancels troop labor and forces the whole squad to regroup before doctrine resumes',()=>{const c=fresh(),living=c.s.party.filter(u=>u.hp>0),enemy=c.zone().enemies.find(e=>e.type==='mob');living[0].order={type:'build',id:'fake'};living[1].order={type:'gather',id:c.zone().nodes[0].id};Object.assign(enemy,{aggro:true,heroParticipated:true,x:c.hero.x+120,y:c.hero.y});c.recallParty();assert(c.s.recallActive);assert(living.every(u=>u.order===null));Object.assign(c.hero,{x:c.hero.x+260,y:c.hero.y+100});const before=living.map(u=>Math.hypot(u.x-c.hero.x,u.y-c.hero.y));for(let i=0;i<8;i++)c.updateParty(.1);const after=living.map(u=>Math.hypot(u.x-c.hero.x,u.y-c.hero.y));assert(after.every((d,i)=>d<before[i]),'recalled companions close distance to hero even during combat');});
test('Expedition 2 unlocks recruitment and gathering while town hiring stops at three total followers',()=>{const c=fresh();c.hero.gold=1000;assert(!c.recruit('soldier'));assert(!c.gather(c.zone().nodes[0].id));c.s.rescued.thorn=true;assert(c.trainExpedition('thorn'));assert.equal(c.s.expeditionRank,2);assert(c.recruit('soldier'));assert.equal(c.rosterCount(),3);c.s.party[2].active=false;c.s.party[1].hp=0;assert(!c.recruit('archer'),'town counts resting and fallen followers toward its hard limit');const node=c.zone().nodes[0];node.amount=12;for(const g of c.zone().enemies.filter(e=>e.mini===node.mini))slay(c,g,false);assert(c.gather(node.id));assert(c.activeLivingParty().every(u=>u.order?.type==='gather'),'all idle active troops take the resource assignment');});
test('Barracks can hire unlimited reserves while active group size obeys Expedition and barracks support',()=>{const c=fresh();c.hero.gold=10000;c.s.rescued.thorn=true;c.trainExpedition('thorn');const b={id:'barracks-test',x:c.hero.x+80,y:c.hero.y,progress:4,queue:0,queueType:null,kind:'barracks',name:'Barracks',theme:'vale',icon:'🏕️',full:false,upgradeProgress:0,upgradePaid:false};c.zone().buildings.push(b);assert(!c.train(b.id,'worker'));for(let i=0;i<8;i++){assert(c.train(b.id,i%2?'archer':'soldier'));c.updateParty(4.1);}assert.equal(c.rosterCount(),10);assert.equal(c.activeParty().length,3);assert.equal(c.s.party.filter(u=>u.active===false).length,7);assert.deepEqual(['worker','soldier','archer'].map(t=>c.barracksRecruitPrice(t)),[0,60,85]);});
test('Existing saves convert legacy Workers into Soldiers without losing carried resources or health proportion',()=>{const c=fresh(),s=c.snapshot(),u=s.party[0];u.type='worker';u.icon='👷';u.damage=4;u.maxHp=100;u.hp=40;u.carry=27;const r=Campaign.restore(s),v=r.s.party[0];assert.equal(v.type,'soldier');assert.equal(v.icon,'⚔️');assert.equal(v.damage,12);assert.equal(v.carry,27);assert(Math.abs(v.hp/v.maxHp-.4)<.02);assert(!r.s.party.some(x=>x.type==='worker'));});
test('Barracks specialist roster keeps unique teachers and replaces redundant lower services',()=>{const c=fresh();c.s.rescued.thorn=true;assert.deepEqual(c.barracksSpecialists().map(s=>s.family),['thorn']);c.s.rescued.mire=true;let ids=c.barracksSpecialists().map(s=>s.family);assert(ids.includes('thorn')&&ids.includes('mire'),'Mira stays while skill 2 remains unlearned');c.hero.skills[1]=1;ids=c.barracksSpecialists().map(s=>s.family);assert(!ids.includes('thorn')&&ids.includes('mire'),'Sela replaces Mira once Mira has no unique teaching left');c.s.rescued.crypt=true;c.s.rescued.mine=true;c.s.rescued.archive=true;ids=c.barracksSpecialists().map(s=>s.family);assert(!ids.includes('crypt')&&ids.includes('mine'),'Highland smith replaces village smith');assert(ids.includes('archive'),'Neri remains because alchemy is unique');});
test('Barracks require one troop builder while the hero remains free',()=>{const c=fresh();c.hero.gold=1000;assert(c.build());const b=c.zone().buildings.at(-1),builder=c.s.party.find(u=>u.order?.type==='build'&&u.order.id===b.id);assert(builder&&['soldier','archer'].includes(builder.type));assert.equal(b.progress,0);const hero={x:c.hero.x,y:c.hero.y};for(let i=0;i<30&&b.progress===0;i++)c.updateParty(.1);assert.equal(c.hero.x,hero.x);assert.equal(c.hero.y,hero.y);assert(b.progress>0&&b.progress<4,'assigned troop starts building while hero remains independent');c.recallParty();const paused=b.progress;for(let i=0;i<5;i++)c.updateParty(.1);assert.equal(b.progress,paused,'Recall pauses construction without losing progress');c.s.recallActive=false;assert(c.assignBuilder(b.id));c.enter('crypt');const gold=c.hero.gold;assert(!c.build());assert.equal(c.hero.gold,gold);});
test('Barracks treat wounded living companions while fallen recovery stays separate',()=>{const c=fresh();c.hero.gold=100;c.s.party[0].hp=20;c.s.party[1].hp=0;const wounded=c.s.party[0],fallen=c.s.party[1];assert(c.treatCompanions());assert.equal(c.hero.gold,70);assert.equal(wounded.hp,wounded.maxHp);assert.equal(fallen.hp,0);assert(!c.treatCompanions(),'no wounded living companions means no charge');assert.equal(c.hero.gold,70);assert(c.recover());assert.equal(c.hero.gold,30);assert(fallen.hp>0&&fallen.hp===fallen.maxHp);});
test('Barracks treatment is blocked during nearby combat and spends no gold',()=>{const c=fresh();c.hero.gold=100;c.s.party[0].hp=20;const e=c.zone().enemies.find(e=>e.type==='mob');Object.assign(e,{x:c.hero.x+100,y:c.hero.y,aggro:true});assert(!c.treatCompanions());assert.equal(c.hero.gold,100);assert.equal(c.s.party[0].hp,20);});
test('Existing companions gain their level-scaled max HP whenever the hero levels without erasing wounds or reviving fallen units',()=>{const c=fresh(),soldier=c.s.party.find(u=>u.type==='soldier'),archer=c.s.party.find(u=>u.type==='archer');soldier.hp-=20;archer.hp=0;const soldierMax=soldier.maxHp,archerMax=archer.maxHp,soldierHp=soldier.hp;c.xp(120);assert.equal(c.hero.level,2);assert.equal(soldier.maxHp,soldierMax+12);assert.equal(soldier.hp,soldierHp+12,'living companion keeps the same missing-health amount');assert.equal(archer.maxHp,archerMax+12);assert.equal(archer.hp,0,'fallen companion remains fallen');c.xp(240);assert.equal(c.hero.level,3);assert.equal(soldier.maxHp,soldierMax+24);assert.equal(archer.maxHp,archerMax+24);});
test('Succession preserves gold, all world facts and equipment, resets XP/skills/talents and prompts at first death',()=>{const c=fresh(.9,{succession:true});slay(c,boss(c,'thorn'));c.rescue('thorn');c.hero.gold=888;c.hero.level=12;c.hero.xp=72;c.hero.skills=[3,3,2,1,1,1,1,0];c.hero.talents=[2,1,2,1];c.hero.weapon=1;c.die();assert(c.s.challenge.pending);assert.deepEqual(c.s.challenge.fallen,['paladin']);assert(!c.successor('paladin'));const restored=Campaign.restore(c.snapshot());assert(restored.s.challenge.pending);assert(restored.successor('mage'));assert.equal(restored.hero.level,1);assert.equal(restored.hero.xp,0);assert.equal(restored.hero.gold,710);assert.equal(restored.hero.weapon,1);assert.deepEqual(restored.hero.skills,[1,0,0,0,0,0,0,0]);assert.deepEqual(restored.hero.talents,[0,0,0,0]);assert(restored.s.normal.thorn&&restored.s.rescued.thorn);assert.equal(restored.s.zone,'vale');});
test('Every death mode removes twenty percent of carried gold',()=>{for(const [mode,options]of [['normal',{}],['nightmare',{}],['normal',{succession:true}]]){const c=new Campaign(mode,'paladin',()=>.9,options);c.hero.gold=100;c.die();assert.equal(c.hero.gold,80,mode+' '+(options.succession?'succession':'standard'));}});
test('Second succession death automatically selects last unused class; third is terminal across reload',()=>{const c=fresh(.9,{succession:true});c.die();c.successor('mage');c.die();assert.equal(c.hero.class,'ranger');assert(!c.s.challenge.pending);assert.deepEqual(c.s.challenge.fallen,['paladin','mage']);c.die();assert(c.s.challenge.gameOver);const restored=Campaign.restore(c.snapshot());const time=restored.s.time;restored.tick(.1);assert.equal(restored.s.time,time);assert(!restored.successor('paladin'));});
test('Malformed saves reject contradictory succession and peace facts without mutating current state',()=>{const c=fresh(),before=c.snapshot();for(const mutate of [s=>s.hero.gold=-1,s=>s.hero.skills[1]=99,s=>s.challenge.fallen=['paladin','paladin'],s=>s.challenge.pending=true,s=>s.phase='peace',s=>s.party[0].hp=1e20,s=>s.earlyRoll.crypt=true,s=>s.zones.vale.enemies[0].home.x=Infinity]){const s=c.snapshot();mutate(s);assert.throws(()=>Campaign.restore(s));assert.deepEqual(c.snapshot(),before);}});
console.log('\n'+passed+' expanded campaign checks passed.');
